INSERT INTO categories (id, code, name_ar, name_en, description, icon, color_hex, order_index) VALUES
(1, 'morning', 'أذكار الصباح', 'Morning Azkar', 'حصن المسلم اليومي في الصباح ويبدأ من بعد الفجر حتى الشروق أو الضحى', 'wb_sunny', '#D97706', 1),
(2, 'evening', 'أذكار المساء', 'Evening Azkar', 'حفظ العبد وتحصينه في المساء ويبدأ من بعد العصر حتى غروب الشمس والليل', 'nights_stay', '#4338CA', 2),
(3, 'sleep', 'أذكار النوم', 'Sleep Azkar', 'أذكار ما قبل النوم لحفظ النفس وطرد الشياطين', 'bedtime', '#1E293B', 3),
(4, 'waking_up', 'أذكار الاستيقاظ', 'Waking Up Azkar', 'شكر الله على نعمة الحياة وانبعاث الروح', 'alarm', '#059669', 4),
(5, 'istighfar', 'الاستغفار والتوبة', 'Istighfar & Repentance', 'أعظم صيغ طلب المغفرة وتفريج الكروب وجلب الرزق', 'refresh', '#2563EB', 5),
(6, 'wudu', 'أذكار الوضوء', 'Wudu Azkar', 'سنن الطهارة قبل وبعد الوضوء وأجر فتح أبواب الجنة', 'water_drop', '#0EA5E9', 6),
(7, 'masjid', 'أذكار المسجد', 'Mosque Azkar', 'أدعية الذهاب للمسجد، ودخول وخروج بيت الله، والأذكار بعد الصلوات', 'mosque', '#047857', 7),
(8, 'tasbeeh', 'التسبيح والتحميد', 'Tasbeeh & Praises', 'كنوز الذكر وغراس الجنة والباقيات الصالحات', 'circle', '#10B981', 8),
(9, 'prophetic_duas', 'أدعية نبوية وقرآنية', 'Prophetic Duas', 'جوامع الدعاء الثابتة في الكتاب والسنة النبوية', 'auto_stories', '#7C3AED', 9),
(10, 'relief_duas', 'أدعية تفريج الهم والكرب', 'Relief & Comfort Duas', 'أدعية إزالة الحزن وتفريج الهم وقضاء الدين', 'healing', '#DC2626', 10);
INSERT INTO azkar (category_id, item_order, text_ar, target_count, fadl_virtue, reference_sanad) VALUES
(1, 1, 'أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ لِلَّهِ، وَالْحَمْدُ لِلَّهِ، لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، رَبِّ أَسْأَلُكَ خَيْرَ مَا فِي هَذَا الْيَوْمِ وَخَيْرَ مَا بَعْدَهُ، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا فِي هَذَا الْيَوْمِ وَشَرِّ مَا بَعْدَهُ، رَبِّ أَعُوذُ بِكَ مِنَ الْكَسَلِ، وَسُوءِ الْكِبَرِ، رَبِّ أَعُوذُ بِكَ مِنْ عَذَابٍ فِي النَّارِ وَعَذَابٍ فِي الْقَبْرِ.', 1, 'إقرار بالملك والحمد لله والتعوذ من الكسل وعذاب القبر والنار', 'رواه مسلم'),
(1, 2, 'اللَّهُمَّ أَنْتَ رَبِّي لاَ إِلَهَ إِلاَّ أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ، أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ، أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ، وَأَبُوءُ بِذَنْبِي فَاغْفِرْ لِي فَإِنَّهُ لاَ يَغْفِرُ الذُّنُوبَ إِلاَّ أَنْتَ.', 1, 'سيد الاستغفار؛ من قالها موقناً بها حين يمسي فمات دخل الجنة، وكذلك حين يصبح', 'رواه البخاري'),
(1, 3, 'اللَّهُمَّ بِكَ أَصْبَحْنَا، وَبِكَ أَمْسَيْنَا، وَبِكَ نَحْيَا، وَبِكَ نَمُوتُ وَإِلَيْكَ النُّشُورُ.', 1, 'الاستعانة بالله في تقلب الليل والنهار والاعتراف بالبعث والنشور', 'رواه الترمذي وصححه الألباني'),
(1, 4, 'اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَافِيَةَ فِي الدُّنْيَا وَالآخِرَةِ، اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي دِينِي وَدُنْيَايَ وَأَهْلِي وَمَالِي، اللَّهُمَّ اسْتُرْ عَوْرَاتِي وَآمِنْ رَوْعَاتِي، اللَّهُمَّ احْفَظْنِي مِنْ بَيْنِ يَدَيَّ وَمِنْ خَلْفِي وَعَنْ يَمِينِي وَعَنْ شِمَالِي وَمِنْ فَوْقِي، وَأَعُوذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِي.', 1, 'دعاء الحفظ الشامل من جميع الجهات الست وحفظ الدين والأهل والمال', 'رواه أبو داود وصححه الألباني'),
(1, 5, 'بِسْمِ اللَّهِ الَّذِي لاَ يَضُرُّ مَعَ اسْمِهِ شَيْءٌ فِي الأَرْضِ وَلاَ فِي السَّمَاءِ وَهُوَ السَّمِيعُ الْعَلِيمُ.', 3, 'من قالها ثلاثاً إذا أصبح وثلاثاً إذا أمسى لم يضره شيء', 'رواه أبو داود والترمذي'),
(1, 6, 'رَضِيتُ بِاللَّهِ رَبًّا، وَبِالإِسْلاَمِ دِينًا، وَبِمُحَمَّدٍ صلى الله عليه وسلم نَبِيًّا.', 3, 'من قالها حين يصبح وحين يمسي كان حقاً على الله أن يرضيه يوم القيامة', 'رواه أحمد والترمذي'),
(1, 7, 'يَا حَيُّ يَا قَيُّومُ بِرَحْمَتِكَ أَسْتَغِيثُ، أَصْلِحْ لِي شَأْنِي كُلَّهُ، وَلاَ تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ.', 1, 'طلب صلاح الشأن كله والافتقار إلى معية الله ولطفه', 'رواه الحاكم وصححه الألباني'),
(1, 8, 'سُبْحَانَ اللَّهِ وَبِحَمْدِهِ: عَدَدَ خَلْقِهِ، وَرِضَا نَفْسِهِ، وَزِنَةَ عَرْشِهِ، وَمِدَادَ كَلِمَاتِهِ.', 3, 'تعدل ساعات طويلة من الذكر والتسبيح في الأجر والميزان', 'رواه مسلم'),
(1, 9, 'حَسْبِيَ اللَّهُ لاَ إِلَهَ إِلاَّ هُوَ عَلَيْهِ تَوَكَّلْتُ وَهُوَ رَبُّ الْعَرْشِ الْعَظِيمِ.', 7, 'من قالها سبع مرات حين يصبح وحين يمسي كفاه الله ما أهمه من أمر الدنيا والآخرة', 'رواه أبو داود'),
(1, 10, 'سُبْحَانَ اللَّهِ وَبِحَمْدِهِ.', 100, 'حُطّت خطاياه وإن كانت مثل زبد البحر، ولم يأت أحد يوم القيامة بأفضل مما جاء به', 'رواه مسلم');
INSERT INTO azkar (category_id, item_order, text_ar, target_count, fadl_virtue, reference_sanad) VALUES
(2, 1, 'أَمْسَيْنَا وَأَمْسَى الْمُلْكُ لِلَّهِ، وَالْحَمْدُ لِلَّهِ، لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، رَبِّ أَسْأَلُكَ خَيْرَ مَا فِي هَذِهِ اللَّيْلَةِ وَخَيْرَ مَا بَعْدَهَا، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا فِي هَذِهِ اللَّيْلَةِ وَشَرِّ مَا بَعْدَهَا، رَبِّ أَعُوذُ بِكَ مِنَ الْكَسَلِ، وَسُوءِ الْكِبَرِ، رَبِّ أَعُوذُ بِكَ مِنْ عَذَابٍ فِي النَّارِ وَعَذَابٍ فِي الْقَبْرِ.', 1, 'تحصين المسلم في ليلته والاستعاذة من الشرور والعذاب', 'رواه مسلم'),
(2, 2, 'اللَّهُمَّ بِكَ أَمْسَيْنَا، وَبِكَ أَصْبَحْنَا، وَبِكَ نَحْيَا، وَبِكَ نَمُوتُ وَإِلَيْكَ الْمَصِيرُ.', 1, 'ذكر المساء المأثور واستشعار المصير إلى الله', 'رواه الترمذي'),
(2, 3, 'أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ.', 3, 'من قالها حين يمسي ثلاث مرات لم تضره حمة (لدغة أو سم) في تلك الليلة', 'رواه مسلم'),
(2, 4, 'اللَّهُمَّ أَنْتَ رَبِّي لاَ إِلَهَ إِلاَّ أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ، أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ، أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ، وَأَبُوءُ بِذَنْبِي فَاغْفِرْ لِي فَإِنَّهُ لاَ يَغْفِرُ الذُّنُوبَ إِلاَّ أَنْتَ.', 1, 'سيد الاستغفار عند المساء؛ دخول الجنة لمن مات في ليلته', 'رواه البخاري'),
(2, 5, 'بِسْمِ اللَّهِ الَّذِي لاَ يَضُرُّ مَعَ اسْمِهِ شَيْءٌ فِي الأَرْضِ وَلاَ فِي السَّمَاءِ وَهُوَ السَّمِيعُ الْعَلِيمُ.', 3, 'لم يصبه فجأة بلاء حتى يصبح', 'رواه أبو داود'),
(2, 6, 'آمَنَ الرَّسُولُ بِمَا أُنزِلَ إِلَيْهِ مِن رَّبِّهِ وَالْمُؤْمِنُونَ ۚ كُلٌّ آمَنَ بِاللَّهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّن رُّسُلِهِ ۚ وَقَالُوا سَمِعْنَا وَأَطَعْنَا ۖ غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ * لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا ۚ لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا اكْتَسَبَتْ ۗ رَبَّنَا لَا تُؤَاخِذْنَا إِن نَّسِينَا أَوْ أَخْطَأْنَا ۚ رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَا إِصْرًا كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِن قَبْلِنَا ۚ رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِ ۖ وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَا ۚ أَنتَ مَوْلَانَا فَانصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ.', 1, 'الآيتان من آخر سورة البقرة: من قرأهما في ليلة كفتاه (أي من كل سوء ومكروه)', 'متفق عليه');
INSERT INTO azkar (category_id, item_order, text_ar, target_count, fadl_virtue, reference_sanad) VALUES
(3, 1, 'بِاسْمِكَ رَبِّي وَضَعْتُ جَنْبِي، وَبِكَ أَرْفَعُهُ، فَإِنْ أَمْسَكْتَ نَفْسِي فَارْحَمْهَا، وَإِنْ أَرْسَلْتَهَا فَاحْفَظْهَا بِمَا تَحْفَظُ بِهِ عِبَادَكَ الصَّالِحِينَ.', 1, 'طلب حفظ النفس في النوم والرحمة حال قبضها', 'متفق عليه'),
(3, 2, 'اللَّهُمَّ قِنِي عَذَابَكَ يَوْمَ تَبْعَثُ عِبَادَكَ.', 3, 'كان ﷺ يضع يده اليمنى تحت خده الشريف ويقولها ثلاث مرات', 'رواه أبو داود والترمذي'),
(3, 3, 'اللَّهُمَّ أَسْلَمْتُ نَفْسِي إِلَيْكَ، وَفَوَّضْتُ أَمْرِي إِلَيْكَ، وَوَجَّهْتُ وَجْهِي إِلَيْكَ، وَأَلْجَأْتُ ظَهْرِي إِلَيْكَ، رَغْبَةً وَرَهْبَةً إِلَيْكَ، لاَ مَلْجَأَ وَلاَ مَنْجَا مِنْكَ إِلاَّ إِلَيْكَ، آمَنْتُ بِكِتَابِكَ الَّذِي أَنْزَلْتَ، وَبِنَبِيِّكَ الَّذِي أَرْسَلْتَ.', 1, 'إذا أخذت مضجعك فتوضأ وضوءك للصلاة ثم قلها، فإن مت من ليلتك مت على الفطرة', 'متفق عليه'),
(3, 4, 'اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ ۚ لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ ۚ لَّهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ ۗ مَن ذَا الَّذِي يَشْفَعُ عِندَهُ إِلَّا بِإِذْنِهِ ۚ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحِيطُونَ بِشَيْءٍ مِّنْ عِلْمِهِ إِلَّا بِمَا شَاءَ ۚ وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ ۖ وَلَا يَئُودُهُ حِفْظُهُمَا ۚ وَهُوَ الْعَلِيُّ الْعَظِيمُ.', 1, 'آية الكرسي: لن يزال عليك من الله حافظ ولا يقربك شيطان حتى تصبح', 'رواه البخاري'),
(3, 5, 'سُبْحَانَ اللَّهِ (33)، وَالْحَمْدُ لِلَّهِ (33)، وَاللَّهُ أَكْبَرُ (34).', 1, 'خير للإنسان من خادم ويعطي قوة وبركة في البدن واليوم التالي', 'متفق عليه');
INSERT INTO azkar (category_id, item_order, text_ar, target_count, fadl_virtue, reference_sanad) VALUES
(4, 1, 'الْحَمْدُ لِلَّهِ الَّذِي أَحْيَانَا بَعْدَ مَا أَمَاتَنَا وَإِلَيْهِ النُّشُورُ.', 1, 'شكر الله على استرجاع الروح وبدء يوم جديد في طاعته', 'رواه البخاري'),
(4, 2, 'الْحَمْدُ لِلَّهِ الَّذِي عَافَانِي فِي جَسَدِي، وَرَدَّ عَلَيَّ رُوحِي، وَأَذِنَ لِي بِذِكْرِهِ.', 1, 'شكر نعمة العافية وصحة الجسد والتوفيق لذكر الله', 'رواه الترمذي'),
(4, 3, 'لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ، وَلاَ إِلَهَ إِلاَّ اللَّهُ، وَاللَّهُ أَكْبَرُ، وَلاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ، رَبِّ اغْفِرْ لِي.', 1, 'من تعار من الليل (استيقظ) فقال هذا ثم دعا استجيب له، فإن توضأ وصلى قُبلت صلاته', 'رواه البخاري');
INSERT INTO azkar (category_id, item_order, text_ar, target_count, fadl_virtue, reference_sanad) VALUES
(5, 1, 'أَسْتَغْفِرُ اللَّهَ الْعَظِيمَ الَّذِي لاَ إِلَهَ إِلاَّ هُوَ الْحَيَّ الْقَيُّومَ وَأَتُوبُ إِلَيْهِ.', 3, 'من قالها غُفرت ذنوبه وإن كان قد فر من الزحف', 'رواه أبو داود والترمذي'),
(5, 2, 'رَبِّ اغْفِرْ لِي وَتُبْ عَلَيَّ إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيمُ.', 100, 'كان يُعد لرسول الله ﷺ في المجلس الواحد مائة مرة', 'رواه أبو داود والترمذي'),
(5, 3, 'أَسْتَغْفِرُ اللَّهَ وَأَتُوبُ إِلَيْهِ.', 100, 'تفريج الهموم وجلب الأرزاق والأمطار والذرية الطيبة', 'رواه البخاري ومسلم'),
(5, 4, 'اللَّهُمَّ إِنِّي ظَلَمْتُ نَفْسِي ظُلْمًا كَثِيرًا، وَلاَ يَغْفِرُ الذُّنُوبَ إِلاَّ أَنْتَ، فَاغْفِرْ لِي مَغْفِرَةً مِنْ عِنْدِكَ، وَارْحَمْنِي إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ.', 1, 'دعاء عظيم علمه النبي ﷺ لأبي بكر الصديق رضي الله عنه ليقوله في صلاته ودبر صلاته', 'متفق عليه');
INSERT INTO azkar (category_id, item_order, text_ar, target_count, fadl_virtue, reference_sanad) VALUES
(6, 1, 'بِسْمِ اللَّهِ.', 1, 'تقال في أول الوضوء؛ لا وضوء لمن لم يذكر اسم الله عليه', 'رواه أبو داود وصححه الألباني'),
(6, 2, 'أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ.', 1, 'فُتحت له أبواب الجنة الثمانية يدخل من أيها شاء', 'رواه مسلم'),
(6, 3, 'اللَّهُمَّ اجْعَلْنِي مِنَ التَّوَّابِينَ وَاجْعَلْنِي مِنَ الْمُتَطَهِّرِينَ.', 1, 'الجمع بين طهارة الباطن بالتوبة وطهارة الظاهر بالماء', 'رواه الترمذي وصححه الألباني'),
(6, 4, 'سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ.', 1, 'طُبع عليها بطابع ثم رفعت تحت العرش فلم تكسر إلى يوم القيامة', 'رواه النسائي وصححه الألباني');
INSERT INTO azkar (category_id, item_order, text_ar, target_count, fadl_virtue, reference_sanad) VALUES
(7, 1, 'اللَّهُمَّ اجْعَلْ فِي قَلْبِي نُورًا، وَفِي لِسَانِي نُورًا، وَفِي سَمْعِي نُورًا، وَفِي بَصَرِي نُورًا، وَمِنْ فَوْقِي نُورًا، وَمِنْ تَحْتِي نُورًا، وَعَنْ يَمِينِي نُورًا، وَعَنْ شِمَالِي نُورًا، وَمِنْ أَمَامِي نُورًا، وَمِنْ خَلْفِي نُورًا، وَاجْعَلْ فِي نَفْسِي نُورًا، وَأَعْظِمْ لِي نُورًا.', 1, 'دعاء المشي والذهاب إلى المسجد لإسباغ النور التام على العبد', 'رواه مسلم'),
(7, 2, 'أَعُوذُ بِاللَّهِ الْعَظِيمِ، وَبِوَجْهِهِ الْكَرِيمِ، وَسُلْطَانِهِ الْقَدِيمِ، مِنَ الشَّيْطَانِ الرَّجِيمِ. بِسْمِ اللَّهِ، وَالصَّلاَةُ وَالسَّلاَمُ عَلَى رَسُولِ اللَّهِ، اللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ.', 1, 'دعاء دخول المسجد (يُقدّم رجله اليمنى)؛ عُصم من الشيطان سائر اليوم', 'رواه أبو داود ومسلم'),
(7, 3, 'بِسْمِ اللَّهِ، وَالصَّلاَةُ وَالسَّلاَمُ عَلَى رَسُولِ اللَّهِ، اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ، اللَّهُمَّ اعْصِمْنِي مِنَ الشَّيْطَانِ الرَّجِيمِ.', 1, 'دعاء الخروج من المسجد (يُقدّم رجله اليسرى)', 'رواه مسلم وابن ماجه'),
(7, 4, 'أَسْتَغْفِرُ اللَّهَ (3)، اللَّهُمَّ أَنْتَ السَّلاَمُ وَمِنْكَ السَّلاَمُ، تَبَارَكْتَ يَا ذَا الْجَلاَلِ وَالإِكْرَامِ.', 1, 'يقال مباشرة بعد التسليم من الصلاة المفروضة', 'رواه مسلم'),
(7, 5, 'لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، اللَّهُمَّ لاَ مَانِعَ لِمَا أَعْطَيْتَ، وَلاَ مُعْطِيَ لِمَا مَنَعْتَ، وَلاَ يَنْفَعُ ذَا الْجَدِّ مِنْكَ الْجَدُّ.', 1, 'دبر كل صلاة مكتوبة', 'متفق عليه');
INSERT INTO azkar (category_id, item_order, text_ar, target_count, fadl_virtue, reference_sanad) VALUES
(8, 1, 'سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ، وَلاَ إِلَهَ إِلاَّ اللَّهُ، وَاللَّهُ أَكْبَرُ.', 100, 'أحب الكلام إلى الله، وهن الباقيات الصالحات وغراس الجنة', 'رواه مسلم'),
(8, 2, 'سُبْحَانَ اللَّهِ وَبِحَمْدِهِ، سُبْحَانَ اللَّهِ الْعَظِيمِ.', 100, 'كلمتان خفيفتان على اللسان، ثقيلتان في الميزان، حبيبتان إلى الرحمن', 'متفق عليه'),
(8, 3, 'لاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ.', 100, 'كنز من كنوز الجنة وباب من أبواب دفع البلاء والهم', 'متفق عليه'),
(8, 4, 'لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ.', 100, 'كانت له عدل عشر رقاب، وكُتبت له مائة حسنة، ومُحيت عنه مائة سيئة', 'متفق عليه');
INSERT INTO azkar (category_id, item_order, text_ar, target_count, fadl_virtue, reference_sanad) VALUES
(9, 1, 'رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ.', 1, 'أكثر دعاء كان يدعو به النبي ﷺ لجمعه خير الدنيا والآخرة والوقاية من النار', 'متفق عليه'),
(9, 2, 'يَا مُقَلِّبَ الْقُلُوبِ ثَبِّتْ قَلْبِي عَلَى دِينِكَ.', 1, 'تثبيت الفؤاد على الهداية والإيمان في أوقات الفتن', 'رواه الترمذي وأحمد'),
(9, 3, 'اللَّهُمَّ إِنِّي أَسْأَلُكَ الْهُدَى وَالتُّقَى وَالْعَفَافَ وَالْغِنَى.', 1, 'طلب صفوة خصال الإيمان والكفاية والعفة', 'رواه مسلم'),
(9, 4, 'اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ إِنَّكَ حَمِيدٌ مَجِيدٌ، اللَّهُمَّ بَارِكْ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ كَمَا بَارَكْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ إِنَّكَ حَمِيدٌ مَجِيدٌ.', 10, 'من صلى عليّ صلاة صلى الله عليه بها عشراً وحُطت عنه عشر خطيئات ورُفعت له عشر درجات', 'رواه النسائي وأحمد');
INSERT INTO azkar (category_id, item_order, text_ar, target_count, fadl_virtue, reference_sanad) VALUES
(10, 1, 'لاَ إِلَهَ إِلاَّ أَنْتَ سُبْحَانَكَ إِنِّي كُنْتُ مِنَ الظَّالِمِينَ.', 1, 'دعوة ذي النون إذ دعا بها في بطن الحوت؛ لم يدعُ بها رجل مسلم في شيء قط إلا استجاب الله له', 'رواه الترمذي والحاكم'),
(10, 2, 'لاَ إِلَهَ إِلاَّ اللَّهُ الْعَظِيمُ الْحَلِيمُ، لاَ إِلَهَ إِلاَّ اللَّهُ رَبُّ الْعَرْشِ الْعَظِيمِ، لاَ إِلَهَ إِلاَّ اللَّهُ رَبُّ السَّمَاوَاتِ وَرَبُّ الأَرْضِ وَرَبُّ الْعَرْشِ الْكَرِيمِ.', 1, 'دعاء الكرب العظيم الذي كان يدعو به رسول الله ﷺ عند الشدائد', 'متفق عليه'),
(10, 3, 'اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَالْعَجْزِ وَالْكَسَلِ، وَالْبُخْلِ وَالْجُبْنِ، وَضَلَعِ الدَّيْنِ وَغَلَبَةِ الرِّجَالِ.', 1, 'دعاء شامل لتفريج الهموم وقضاء الديون والنجاة من قهر الرجال', 'رواه البخاري'),
(10, 4, 'اللَّهُمَّ رَحْمَتَكَ أَرْجُو فَلاَ تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ، وَأَصْلِحْ لِي شَأْنِي كُلَّهُ، لاَ إِلَهَ إِلاَّ أَنْتَ.', 1, 'دعوات المكروب وتفريج الكربات ونزول السكينة', 'رواه أبو داود وأحمد');
INSERT INTO tasbeeh_presets (id, title, target_count, virtue, order_index) VALUES
(1, 'سُبْحَانَ اللَّهِ', 33, 'تنزيه الله عما لا يليق به وثواب مائة حسنة', 1),
(2, 'الْحَمْدُ لِلَّهِ', 33, 'تملأ الميزان بالخير والبركة', 2),
(3, 'اللَّهُ أَكْبَرُ', 34, 'تكبير وتعظيم لشأن الخالق سبحانه', 3),
(4, 'أَسْتَغْفِرُ اللَّهَ وَأَتُوبُ إِلَيْهِ', 100, 'ممحاة للذنوب ومفتاح للرزق وتفريج الكروب', 4),
(5, 'لاَ إِلَهَ إِلاَّ اللَّهُ', 100, 'أفضل الذكر وخير ما قال النبيون', 5),
(6, 'اللَّهُمَّ صَلِّ وَسَلِّمْ عَلَى نَبِيِّنَا مُحَمَّدٍ', 100, 'كفاية للهم وغفران للذنب وشفاعة يوم القيامة', 6),
(7, 'لاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ', 100, 'كنز عظيم من كنوز الجنة', 7),
(8, 'سُبْحَانَ اللَّهِ وَبِحَمْدِهِ سُبْحَانَ اللَّهِ الْعَظِيمِ', 100, 'ثقيلتان في الميزان حبيبتان إلى الرحمن', 8);
